#include "layout_resource.hpp"
#include <cstdio>
int main(int argc,char**argv){try{if(argc<2||argc>3)return 2;WiiAssets disc(std::filesystem::u8path(argv[1]));Rarc arc(disc.readFile(argc==3?argv[2]:"/LayoutData/DPDPointer.arc"));for(const auto& file:arc.files){auto raw=arc.readFile(file.path);if(raw.size()<16||std::memcmp(raw.data(),"RLYT",4))continue;auto layout=decodeLayoutResource(BinaryView(raw));for(const auto& pane:layout.panes)if(pane.kind=="pic1"||pane.kind=="wnd1"){const auto& material=layout.materials.at(pane.material);std::printf("%s %s pane=%s UV=%zu material=%u:%s textures=%zu generators=%zu size=(%.2f,%.2f)\n",file.path.c_str(),pane.kind.c_str(),pane.name.c_str(),pane.uv.size(),pane.material,material.name.c_str(),material.textures.size(),material.coordinateGenerators.size(),pane.size[0],pane.size[1]);}BinaryView data(raw);size_t offset=data.u16(12);for(unsigned i=0;i<data.u16(14);++i){auto length=data.u32(offset+4);auto block=data.sub(offset,length);if(block.tag(0)=="wnd1"){auto content=block.u32(96);if(content+26<=length){auto intended=block.u16(content+16),old=block.u16(content+24);std::printf("WINDOW INDEX %s correct=%u old=%u",layoutFixedName(block,12,16).c_str(),intended,old);if(old<layout.materials.size())std::printf(" oldMaterial=%s oldTextures=%zu oldGenerators=%zu",layout.materials[old].name.c_str(),layout.materials[old].textures.size(),layout.materials[old].coordinateGenerators.size());std::puts("");}}offset+=length;}}return 0;}catch(const std::exception&e){std::fprintf(stderr,"%s\n",e.what());return 1;}}